/****************************************************************************
 * ai_agent Skill 安装 + 主动 Tool 调度
 ****************************************************************************/

#include "ew_agent.h"
#include "ew_agent_tool.h"

#include <stdio.h>
#include <string.h>

#ifdef __NuttX__
#include <sys/stat.h>
#include <unistd.h>
#endif

#ifndef EW_AGENT_SKILLS_DIR
#define EW_AGENT_SKILLS_DIR "/data/ai_agent/skills/"
#endif

#ifndef EW_AGENT_SKILL_NAME
#define EW_AGENT_SKILL_NAME "approach-warn"
#endif

static const char *g_approach_warn_skill =
    "# 接近提醒\n"
    "\n"
    "毫米波雷达端侧判决后，由 ai_agent 主动调用 Tool `approach_alert` 执行"
    "蜂鸣与 LCD 变色。LLM 不参与测距与门限计算。\n"
    "\n"
    "## When to use\n"
    "当 LD2451 检测到侧后靠近目标且 ew_decide 输出 SOFT/STRONG/EMERGENCY 时；"
    "或用户询问「接近预警怎么工作」「告警档位」时说明流程。\n"
    "\n"
    "## How to use\n"
    "1. 判决已在 ew_ld2451 + ew_decide 完成，禁止用 LLM 估算距离或 TTC。\n"
    "2. 主动执行 Tool `approach_alert`，参数示例：\n"
    "   `{\"level\":\"strong\",\"reason\":\"R 12.3m approaching\"}`\n"
    "3. level 取值：none | soft | strong | emergency（或 0–3）。\n"
    "4. Tool 内部只调用 alert_output(level, reason)，串口应出现 "
    "`[alert_output] level=...`。\n"
    "5. 解除告警时 level=none。\n"
    "\n"
    "## Example\n"
    "雷达 latch STRONG @ 12m → 主动 approach_alert "
    "{\"level\":\"strong\",\"reason\":\"R 12.0m approaching\"}\n"
    "→ 屏橙 WARN + 蜂鸣 + 日志 `[alert_output] level=STRONG ...`\n";

static void install_skill_file(void)
{
#ifdef __NuttX__
  char path[128];
  FILE *f;

  mkdir("/data", 0755);
  mkdir("/data/ai_agent", 0755);
  mkdir(EW_AGENT_SKILLS_DIR, 0755);

  snprintf(path, sizeof(path), "%s%s.md", EW_AGENT_SKILLS_DIR,
           EW_AGENT_SKILL_NAME);

  f = fopen(path, "r");
  if (f != NULL) {
    fclose(f);
    printf("[ew_agent] skill exists: %s\n", path);
    fflush(stdout);
    return;
  }

  f = fopen(path, "w");
  if (f == NULL) {
    printf("[ew_agent] skill write failed: %s\n", path);
    fflush(stdout);
    return;
  }
  fputs(g_approach_warn_skill, f);
  fclose(f);
  printf("[ew_agent] installed skill: %s\n", path);
  fflush(stdout);
#else
  printf("[ew_agent] stub skill install\n");
#endif
}

void ew_agent_init(void)
{
  install_skill_file();
  printf("[ew_agent] Tool approach_alert ready (calls alert_output only)\n");
  fflush(stdout);
}

int ew_agent_proactive_alert(ew_alert_level_t level, float range_m,
                             const char *reason)
{
  char ui_reason[64];
  char out[128];

  if (level != EW_ALERT_NONE && range_m > 0.0f) {
    snprintf(ui_reason, sizeof(ui_reason), "R %.1fm", range_m);
    if (reason == NULL || reason[0] == '\0') {
      reason = ui_reason;
    }
  } else if (reason == NULL) {
    reason = "";
  }

  printf("[ew_agent] proactive approach_alert level=%s range=%.1fm\n",
         ew_alert_level_name(level), range_m);
  fflush(stdout);

  return ew_agent_tool_approach_alert(level, reason, out, sizeof(out));
}

/****************************************************************************
 * ai_agent 进程侧 Tool approach_alert（IPC 版）
 *
 * ai_agent 与 ew 是不同 NuttX 应用；此处通过 /data/ew_alert.req 通知
 * 常驻 ew boot UI，并打印与 alert_output 一致的日志行供串口验收。
 * 编译进 packages/ai_agent（由 sync_and_build.sh 注入）。
 ****************************************************************************/

#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>

#define EW_ALERT_REQ "/data/ew_alert.req"

static const char *level_name(int level)
{
  switch (level) {
    case 1: return "SOFT";
    case 2: return "STRONG";
    case 3: return "EMERGENCY";
    default: return "NONE";
  }
}

static int level_from_json(const char *input_json, int *level_out,
                           char *reason, unsigned reason_sz)
{
  const char *p;
  char buf[16];

  *level_out = 0;
  if (reason != NULL && reason_sz > 0) {
    reason[0] = '\0';
  }
  if (input_json == NULL) {
    return 0;
  }

  p = strstr(input_json, "\"level\"");
  if (p != NULL) {
    p = strchr(p, ':');
    if (p != NULL) {
      unsigned i = 0;

      p++;
      while (*p == ' ' || *p == '\t') {
        p++;
      }
      if (*p == '"') {
        p++;
        while (*p != '\0' && *p != '"' && i + 1 < sizeof(buf)) {
          buf[i++] = *p++;
        }
        buf[i] = '\0';
        if (strcmp(buf, "soft") == 0 || strcmp(buf, "SOFT") == 0 ||
            strcmp(buf, "1") == 0) {
          *level_out = 1;
        } else if (strcmp(buf, "strong") == 0 || strcmp(buf, "STRONG") == 0 ||
                   strcmp(buf, "2") == 0) {
          *level_out = 2;
        } else if (strcmp(buf, "emergency") == 0 ||
                   strcmp(buf, "EMERGENCY") == 0 ||
                   strcmp(buf, "crit") == 0 || strcmp(buf, "3") == 0) {
          *level_out = 3;
        } else {
          *level_out = 0;
        }
      }
    }
  }

  p = strstr(input_json, "\"reason\"");
  if (p != NULL && reason != NULL && reason_sz > 0) {
    p = strchr(p, ':');
    if (p != NULL) {
      unsigned o = 0;

      p++;
      while (*p == ' ' || *p == '\t') {
        p++;
      }
      if (*p == '"') {
        p++;
        while (*p != '\0' && *p != '"' && o + 1 < reason_sz) {
          if (*p == '\\' && p[1] != '\0') {
            p++;
          }
          reason[o++] = *p++;
        }
        reason[o] = '\0';
      }
    }
  }
  return 0;
}

static void queue_alert(int level, const char *reason)
{
  char line[96];
  int fd;

  snprintf(line, sizeof(line), "%d %s\n", level, reason ? reason : "");
  fd = open(EW_ALERT_REQ, O_WRONLY | O_CREAT | O_TRUNC, 0666);
  if (fd < 0) {
    return;
  }
  (void)write(fd, line, strlen(line));
  close(fd);
}

int tool_approach_alert_execute(const char *input_json, char *output,
                                size_t output_size)
{
  int level = 0;
  char reason[64];

  level_from_json(input_json, &level, reason, sizeof(reason));

  printf("[ai_agent] tool approach_alert level=%s reason=%s\n",
         level_name(level), reason);
  printf("[alert_output] level=%s reason=%s\n", level_name(level), reason);
  fflush(stdout);

  queue_alert(level, reason);

  if (output != NULL && output_size > 0) {
    snprintf(output, output_size,
             "{\"ok\":true,\"tool\":\"approach_alert\",\"level\":\"%s\","
             "\"reason\":\"%s\"}",
             level_name(level), reason);
  }
  return 0;
}

#pragma once

#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

int tool_approach_alert_execute(const char *input_json, char *output,
                                size_t output_size);

#ifdef __cplusplus
}
#endif

